static void receive_sync_reply(struct dlm_ls *ls, const struct dlm_rcom *rc_in)
{
	spin_lock_bh(&ls->ls_rcom_spin);
	if (!test_bit(LSFL_RCOM_WAIT, &ls->ls_flags) ||
